import React, { useState } from "react";
import OrarToti from "./OrarToti";

const Orar = () => {
    const [userType, setUserType] = useState(2); // Secretariat default

    const toggleUserType = () => {
        setUserType((prevType) => (prevType === 1 ? 2 : 1));
    };

    return (
        <div>
            <button className="toggle-button" onClick={toggleUserType}>
                Schimbă utilizator ({userType === 1 ? "Studenți" : "Secretariat"})
            </button>
            <OrarToti isEditable={userType === 2} />
        </div>
    );
};

export default Orar;
